package com.dsu.extended.ui.components

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.PathParser
import androidx.compose.ui.unit.dp

private fun buildIcon(name: String, viewport: Float, pathData: String): ImageVector =
    ImageVector.Builder(
        name = name,
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = viewport,
        viewportHeight = viewport,
    ).apply {
        addPath(
            pathData = PathParser().parsePathString(pathData).toNodes(),
            fill = SolidColor(Color.Black),
        )
    }.build()

val MagiskIcon: ImageVector by lazy {
    buildIcon("Magisk", 24f, MAGISK_PATH)
}

val ShizukuIcon: ImageVector by lazy {
    buildIcon("Shizuku", 192f, SHIZUKU_PATH)
}

val DhizukuIcon: ImageVector by lazy {
    buildIcon("Dhizuku", 24f, DHIZUKU_PATH)
}

